import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    <View style={styles.screen}>
      <View nativeID="option" style={styles.option}>
        <Text style={styles.text}>Хүргэлттэй авах</Text>
      </View>
      {/* энд бичнэ үү: option-д хүрээ нэм */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, justifyContent: "center" },
  option: { padding: 18, borderRadius: 12 },
  text: { fontSize: 16, fontWeight: "600", color: "#1d4ed8" },
});

registerRootComponent(App);

